body.script:
                    const TOKEN = '';

                    async function poll() {
                        try {
                            const r = await fetch('/sprint-board/kiosk/' + TOKEN + '/data', {
                                method: 'POST',
                                headers: {'Content-Type': 'application/json'},
                                body: JSON.stringify({jsonrpc: '2.0', method: 'call', id: 1, params: {}})
                            });
                            const d = (await r.json()).result;
                            if (!d || d.error) return;
                            render(d);
                        } catch(e) { console.warn('Kiosk poll error:', e); }
                    }

                    function render(d) {
                        const k = d.kpis;
                        // KPIs
                        $('k-pct').textContent  = k.pct + '%';
                        $('k-done').textContent = k.done_tasks + '/' + k.total_tasks;
                        $('k-sp').textContent   = k.done_sp + ' SP';
                        $('k-days').textContent = k.days_left;
                        $('k-prog').style.display = 'block';
                        $('k-prog').style.width = k.pct + '%';
                        $('pct-label').textContent = k.pct + '%';
                        $('sprint-dates').textContent = (d.sprint.start_date||'') + ' → ' + (d.sprint.end_date||'');

                        // Prediction
                        const pred = d.prediction;
                        if (pred) $('k-pred-pct').textContent = pred.pct_chance + '%';

                        // Health
                        const h = d.health;
                        if (h && h.status !== 'unknown') {
                            const colors = {on_track:'#10b981',at_risk:'#f59e0b',critical:'#ef4444'};
                            const bgs    = {on_track:'#d1fae5',at_risk:'#fef3c7',critical:'#fee2e2'};
                            const el = $('k-health');
                            el.style.display = 'inline-block';
                            el.style.background = bgs[h.status]||'#f1f5f9';
                            el.style.color = colors[h.status]||'#94a3b8';
                            el.innerHTML = {on_track:' On track',at_risk:' At risk',critical:' Critical'}[h.status]||h.label;
                        }

                        // Headline IA
                        if (d.board && d.board.headline) {
                            const hl = $('k-headline');
                            hl.textContent = '" ' + d.board.headline + ' "';
                            hl.style.display = 'block';
                        }

                        // Objectives
                        const objs = d.objectives || [];
                        _objData = objs;
                        if (objs.length) {
                            show('sec-objectives');
                            $('cnt-obj').textContent = objs.length;
                            var objContainer = document.getElementById('col-objectives');
                            objContainer.innerHTML = '';
                            objs.forEach(function(o, idx) {
                                var pct = Math.round(o.completion_rate || 0);
                                var isCompleted   = (o.state === 'achieved' || pct >= 100);
                                var isNotAchieved = (o.state === 'not_achieved' || o.state === 'failed');
                                var col = isCompleted ? '#34d399' : (isNotAchieved ? '#ef4444' : (pct >= 50 ? '#6366f1' : '#f59e0b'));
                                var item = document.createElement('div');
                                item.className = 'obj-card';
                                item.style.cursor = 'pointer';
                                item.style.transition = 'border-color .15s, background .15s';
                                if (isCompleted) {
                                    item.style.borderColor = '#34d399';
                                    item.style.background  = 'rgba(52,211,153,.07)';
                                } else if (isNotAchieved) {
                                    item.style.borderColor = '#ef4444';
                                    item.style.background  = 'rgba(239,68,68,.05)';
                                }
                                item.addEventListener('mouseenter', function(){ if (!isCompleted && !isNotAchieved) item.style.borderColor = '#6366f1'; });
                                item.addEventListener('mouseleave', function(){ item.style.borderColor = isCompleted ? '#34d399' : (isNotAchieved ? '#ef4444' : ''); });
                                item.addEventListener('click', function(){ openObjPanel(idx); });
                                // Header row: status icon + name
                                var nameRow = document.createElement('div');
                                nameRow.style.display     = 'flex';
                                nameRow.style.alignItems  = 'center';
                                nameRow.style.gap         = '6px';
                                nameRow.style.marginBottom = '4px';
                                var icon = document.createElement('i');
                                icon.className = isCompleted
                                    ? 'fa fa-circle-check'
                                    : (isNotAchieved ? 'fa fa-circle-xmark' : 'fa fa-circle');
                                icon.style.color      = col;
                                icon.style.fontSize   = '.75rem';
                                icon.style.flexShrink = '0';
                                var name = document.createElement('div');
                                name.className        = 'obj-name';
                                name.style.flex       = '1';
                                name.style.margin     = '0';
                                name.textContent      = o.name;
                                nameRow.appendChild(icon);
                                nameRow.appendChild(name);
                                var bg = document.createElement('div');
                                bg.className = 'obj-bar-bg';
                                var fill = document.createElement('div');
                                fill.className = 'obj-bar-fill';
                                fill.style.background = col;
                                fill.style.width = pct + '%';
                                bg.appendChild(fill);
                                var meta = document.createElement('div');
                                meta.className = 'obj-row';
                                var pctSpan = document.createElement('span');
                                pctSpan.className = 'obj-pct';
                                pctSpan.style.color = col;
                                pctSpan.textContent = pct + '%';
                                var countSpan = document.createElement('span');
                                countSpan.className = 'obj-tasks';
                                countSpan.textContent = (o.task_count > 0)
                                    ? (o.completed_task_count || 0) + '/' + o.task_count + ' tasks'
                                    : 'No tasks';
                                meta.appendChild(pctSpan);
                                meta.appendChild(countSpan);
                                item.appendChild(nameRow);
                                item.appendChild(bg);
                                item.appendChild(meta);
                                objContainer.appendChild(item);
                            });
                        }

                        // Comparison
                        const comp = d.comparison;
                        if (comp) {
                            show('sec-comparison');
                            const vp = comp.vs_prev, va = comp.vs_avg;
                            document.getElementById('col-comparison').innerHTML =
                                compBox('vs prev. sprint', vp.velocity_delta, vp.sprint_name||'') +
                                compBox('vs avg. (' + va.sprint_count + ' sprints)', va.velocity_delta, comp.current_velocity + ' t/day');
                        }

                        // Tareas
                        const tasks = d.tasks || [];
                        const priority = tasks.filter(function(t) { return !t.is_closed && t.is_priority; });
                        const bugs     = tasks.filter(function(t) { return t.is_bug && !t.is_closed && !t.is_priority; });
                        const inprog   = tasks.filter(function(t) { return t.state === '01_in_progress' && !t.is_closed && !t.is_bug && !t.is_priority; });

                        renderTasks('sec-priority','col-priority','cnt-priority', priority, '#f59e0b');
                        renderTasks('sec-bugs',    'col-bug',     'cnt-bug',      bugs,     '#f87171');
                        renderTasks('sec-inprog',  'col-inprog',  'cnt-inprog',   inprog,   '#818cf8');
                    }

                    function compBox(label, delta, sub) {
                        const isPos = delta >= 0;
                        const col = isPos ? '#34d399' : '#f87171';
                        return '
' +
                            '
' + esc(label) + '' +
                            '
' +
                            (isPos ? '↑' : '↓') + ' ' + Math.abs(delta) + '%' +
                            '
' + esc(String(sub)) + '' +
                            '';
                    }

                    function renderTasks(secId, colId, cntId, tasks, dotColor) {
                        if (!tasks.length) { hide(secId); return; }
                        show(secId);
                        document.getElementById(cntId).textContent = tasks.length;
                        document.getElementById(colId).innerHTML = tasks.slice(0, 6).map(function(t) {
                            const proj = t.project_name ? '(' + esc(t.project_name) + ')' : '';
                            const blocked = t.blocked_days ? ' ' + t.blocked_days + 'd' : '';
                            const sp = t.sp ? '' + t.sp + ' SP' : '';
                            return '
' +
                                '
' +
                                proj +
                                '' + esc(t.name) + '' +
                                sp + blocked +
                                '';
                        }).join('');
                    }

                    function $(id) { return document.getElementById(id); }
                    function show(id) { const e = $(id); if(e) e.style.display = ''; }
                    function hide(id) { const e = $(id); if(e) e.style.display = 'none'; }
                    function esc(s) { return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

                    // ── OBJECTIVE → tasks in col-right ──
                    let _objData = [];
                    let _selectedObjIdx = null;

                    function openObjPanel(idx) {
                        _selectedObjIdx = idx;
                        const o = _objData[idx];
                        if (!o) return;
                        $('obj-tasks-title').textContent = o.name;
                        const tasks = o.tasks || [];
                        const done  = tasks.filter(function(t){ return t.is_closed; });
                        const open  = tasks.filter(function(t){ return !t.is_closed; });
                        let html = '';
                        if (!tasks.length) {
                            html = '
Sin tareas relacionadas';
                        } else {
                            if (open.length) html += open.map(function(t){ return taskRow(t, false); }).join('');
                            if (done.length) {
                                html += '
Completed';
                                html += done.map(function(t){ return taskRow(t, true); }).join('');
                            }
                        }
                        $('col-obj-tasks').innerHTML = html;
                        show('sec-obj-tasks');
                        // Marcar objetivo seleccionado
                        document.querySelectorAll('.obj-card').forEach(function(el, i){
                            el.style.borderColor = i === idx ? '#8b5cf6' : '';
                        });
                    }

                    function clearObjTasks() {
                        _selectedObjIdx = null;
                        hide('sec-obj-tasks');
                        document.querySelectorAll('.obj-card').forEach(function(el){ el.style.borderColor = ''; });
                    }

                    function taskRow(t, isDone) {
                        const proj = t.project_name ? '(' + esc(t.project_name) + ')&nbsp;' : '';
                        const sp   = t.sp ? '' + t.sp + ' SP' : '';
                        const dot  = '
';
                        return '
' +
                            dot + proj +
                            '' + esc(t.name) + '' +
                            sp + '';
                    }

                    document.addEventListener('keydown', function(e){ if(e.key === 'Escape') clearObjTasks(); });

                    // ── TEMA CLARO/OSCURO ──
                    function toggleTheme() {
                        const isLight = document.body.classList.toggle('light');
                        localStorage.setItem('kiosk_theme', isLight ? 'light' : 'dark');
                        var ti = document.getElementById('theme-icon'); ti.className = isLight ? 'fa fa-sun' : 'fa fa-moon';
                        document.getElementById('theme-label').textContent = isLight ? 'Dark'  : 'Light';
                    }
                    // Restaurar tema guardado
                    (function(){
                        if (localStorage.getItem('kiosk_theme') === 'light') {
                            document.body.classList.add('light');
                            document.getElementById('theme-icon').className = 'fa fa-sun';
                            document.getElementById('theme-label').textContent = 'Dark';
                        }
                    })();

                    poll();
                    setInterval(poll, 30000);
